fn handle_chat(&mut self, version, rnd, player, data, from: Position, chat: &Chat, misunderstood: bool, debug)

// ── 게이트 1 (chat.rs:9) ── 자기 라인이 보낸 채팅은 무시
if from == player.info.position { return; }          // Position::eq 인라인(entity.rs:563)

// ── 게이트 2 (chat.rs:12) ── rule_scope::position_exists(data.context, from)  [인라인, rule_scope.rs:36~41]
//    tutorial = data.context.tutorial (GameContext+0x38)
//    match from {
//      Top(0)             => tutorial.spawn_top_minion()    // runner.rs:282 : tutorial ∈ {None(0), TopSolo(2), Line(7), Total(8)}
//      Jungle(1)          => tutorial.player_count() 기반   // runner.rs:294 : tutorial ∈ {None(0), JungleOnly(6), Total(8)}
//      Mid(2)             => tutorial.spawn_mid_minion()    // runner.rs:286 : tutorial ∈ {None(0), MidSolo(4), MidBottom(5), Line(7), Total(8)}
//      Bottom(3)|Support(4) => tutorial.spawn_bottom_minion() // runner.rs:290 : tutorial ∈ {None(0), First(1), Bottom(3), MidBottom(5), Line(7), Total(8)}
//    }
if !position_exists(ctx, from) { return; }

// ── 게이트 3 (chat.rs:12) ── 규칙 필터 (본체는 이 범위 밖)
if !rule_scope::chat_allowed(ctx /*&GameContext,64B*/, chat /*&Chat,24B*/) { return; }

// ── 분기 (chat.rs:18) ── 트레이스 여부. **두 경로의 handle_chat_inner 인자는 완전히 동일**
if !ctx.trace_level.is_enabled() {                    // trace.rs:14~15, trace_level == Off(0)
    self.handle_chat_inner(version, rnd, player, data, from, chat, misunderstood, debug);  // chat.rs:19
    return;
}

// ── 트레이스 경로 (chat.rs:22~38) ── 판단은 그대로 하고 전후 상태를 기록만 한다
let plan_before      = self.plan.get_name();                              // chat.rs:22, self+0x5e8
let objective_before = format!("{:?}", self.team_plan.objective);          // chat.rs:23, self+0x517
self.handle_chat_inner(version, rnd, player, data, from, chat, misunderstood, debug);  // chat.rs:24 (동일 호출)
let plan_after       = self.plan.get_name();                              // chat.rs:25
let objective_after  = format!("{:?}", self.team_plan.objective);          // chat.rs:26
self.pending_trace_events.push(PendingTraceEvent {                        // chat.rs:27, self+0x858
    tick:  data.cache.game.<vtable+0x28>(),                               // chat.rs:28 → PendingTraceEvent+0xb0
    event: TraceEventType::CallHandled {                                  // chat.rs:29, tag = 0x800000000000000F
        from,                                    // +128
        chat: format!("{:?}", chat),             // chat.rs:31 → +8
        misunderstood,                           // +132 (u8)
        plan_before,                             // chat.rs:33 → +32
        plan_after,                              // chat.rs:34 → +56
        objective_before,                        // chat.rs:35 → +80
        objective_after,                         // chat.rs:36 → +104
    },
});

// 언와인드 경로(블록 50/54/60/72/100~107)는 String drop_glue 만 — 판정에 무관

// 요약: 이 함수 자체는 **판단을 전혀 하지 않는다**. 세 개의 조기 반환 게이트 +
// 실제 반응(handle_chat_inner) 위임 + 트레이스 기록이 전부다.
// version / rnd / debug 는 읽지 않고 그대로 전달만 한다.
